// ─── Helpers ─────────────────────────────────────────────────────────────────

function base64urlDecode(str: string): string {
  const s = str.replace(/-/g, '+').replace(/_/g, '/');
  const pad = s.length % 4 === 0 ? '' : '='.repeat(4 - (s.length % 4));
  return atob(s + pad);
}

interface DecodedJwt {
  header: Record<string, unknown>;
  payload: Record<string, unknown>;
  signature: string;
  raw: { header: string; payload: string; signature: string };
}

function decodeJwt(token: string): { decoded: DecodedJwt | null; error: string | null } {
  const parts = token.trim().split('.');
  if (parts.length !== 3) return { decoded: null, error: 'JWT must have exactly 3 parts separated by dots.' };
  try {
    const header = JSON.parse(base64urlDecode(parts[0]));
    const payload = JSON.parse(base64urlDecode(parts[1]));
    return { decoded: { header, payload, signature: parts[2], raw: { header: parts[0], payload: parts[1], signature: parts[2] } }, error: null };
  } catch (e: any) {
    return { decoded: null, error: 'Failed to decode: ' + e.message };
  }
}

function formatDate(ts: number): string {
  return new Date(ts * 1000).toLocaleString();
}

function timeRemaining(exp: number): { text: string; expired: boolean } {
  const diff = exp * 1000 - Date.now();
  if (diff <= 0) return { text: 'Expired', expired: true };
  const secs = Math.floor(diff / 1000);
  if (secs < 60) return { text: `${secs}s remaining`, expired: false };
  const mins = Math.floor(secs / 60);
  if (mins < 60) return { text: `${mins}m remaining`, expired: false };
  const hours = Math.floor(mins / 60);
  if (hours < 24) return { text: `${hours}h ${mins % 60}m remaining`, expired: false };
  const days = Math.floor(hours / 24);
  return { text: `${days}d ${hours % 24}h remaining`, expired: false };
}

// ─── Syntax highlight for JSON ───────────────────────────────────────────────

const DATE_CLAIMS = ['exp', 'iat', 'nbf'];
const HIGHLIGHT_CLAIMS = ['iss', 'sub', 'aud', 'jti', 'scope', 'roles'];

function JsonValue({ k, v }: { k?: string; v: unknown }) {
  if (v === null) return <span style={{ color: '#8b949e' }}>null</span>;
  if (typeof v === 'boolean') return <span style={{ color: '#d2a8ff' }}>{String(v)}</span>;
  if (typeof v === 'number') {
    const isDate = k && DATE_CLAIMS.includes(k);
    return (
      <span>
        <span style={{ color: '#f78166' }}>{v}</span>
        {isDate && <span style={{ color: '#8b949e', fontSize: 11, marginLeft: 8 }}>({formatDate(v)})</span>}
      </span>
    );
  }
  if (typeof v === 'string') {
    const isHighlight = k && HIGHLIGHT_CLAIMS.includes(k);
    return <span style={{ color: isHighlight ? theme.colors.accent : '#a5d6ff' }}>"{v}"</span>;
  }
  if (Array.isArray(v)) {
    return (
      <span>
        {'['}
        {v.map((item, i) => (
          <span key={i}><JsonValue v={item} />{i < v.length - 1 ? ', ' : ''}</span>
        ))}
        {']'}
      </span>
    );
  }
  if (typeof v === 'object') {
    const entries = Object.entries(v as Record<string, unknown>);
    return (
      <span>
        {'{'}<br />
        {entries.map(([ek, ev], i) => (
          <div key={ek} style={{ paddingLeft: 16 }}>
            <span style={{ color: '#79c0ff' }}>"{ek}"</span>
            <span style={{ color: '#8b949e' }}>: </span>
            <JsonValue k={ek} v={ev} />
            {i < entries.length - 1 ? ',' : ''}
          </div>
        ))}
        {'}'}
      </span>
    );
  }
  return <span style={{ color: '#8b949e' }}>{String(v)}</span>;
}

function JsonPanel({ data, title }: { data: Record<string, unknown>; title: string }) {
  const entries = Object.entries(data);
  return (
    <PanelBox>
      <PanelTitle>{title}</PanelTitle>
      <PanelBody>
        {'{'}
        {entries.map(([k, v], i) => (
          <div key={k}>
            <span style={{ color: '#79c0ff' }}>"{k}"</span>
            <span style={{ color: '#8b949e' }}>: </span>
            <JsonValue k={k} v={v} />
            {i < entries.length - 1 && <span style={{ color: '#8b949e' }}>,</span>}
            {k === 'exp' && typeof v === 'number' && (() => {
              const { text, expired } = timeRemaining(v);
              return (
                <ExpBadge expired={expired}>
                  {expired ? <ShieldOff size={11} /> : <Shield size={11} />}
                  {text}
                </ExpBadge>
              );
            })()}
          </div>
        ))}
        {'}'}
      </PanelBody>
    </PanelBox>
  );
}

